mapper.select:
SELECT b.community_id AS community_id, max(c.name) AS community_name, coalesce(sum(b.payable), 0) AS payable, coalesce(sum(b.waive_amount), 0) AS waive_amount, coalesce(sum(b.paid_amount), 0) AS paid_amount, count(*) AS bill_count FROM bill b LEFT JOIN community c ON c.tenant_id = b.tenant_id AND c.community_id = b.community_id WHERE b.deleted_at IS NULL AND b.status <> '已作废' AND b.period >= #{fromPeriod} AND b.period <= #{toPeriod}
AND b.community_id = #{communityId}
GROUP BY b.community_id ORDER BY b.community_id
